         #define TLS_CLASS_SPEC __declspec(thread)
      #else
         #define TLS_CLASS_SPEC
      #endif
   #else
     #define TLS_CLASS_SPEC __thread 
   #endif
#else
   #define TLS_CLASS_SPEC
#endif

