// --- Common functions implemented as macros ----------------------------------

#define fla_min( x, y )    \
({                         \
   __typeof__(x) _x = (x); \
   __typeof__(y) _y = (y); \
   _x < _y ? _x : _y;      \
})

#define fla_max( x, y )    \
({                         \
   __typeof__(x) _x = (x); \
   __typeof__(y) _y = (y); \
   _x > _y ? _x : _y;      \
})

#undef signof
#define signof( a, b ) ( (b) >= 0 ? (a) : -(a) )

#ifndef __cplusplus

 #undef exchange
 #define exchange( a, b, temp ) { temp = a; a = b; b = temp; }

#endif

// --- Other macro definitions -------------------------------------------------

#define FLA_NEGATE( a ) \
        ( a.base == FLA_ONE.base ? FLA_MINUS_ONE : FLA_ONE )

#endif

