#define MAC_Apply_G_mx2_ass( m_A, \
                             gamma12, \
                             sigma12, \
                             a1, inc_a1, \
                             a2, inc_a2 ) \
{\
	fla_dim_t              n_iter32  = m_A / ( 4 * 8 ); \
	fla_dim_t              n_left32  = m_A % ( 4 * 8 ); \
	fla_dim_t              n_iter4   = n_left32 / ( 4 * 1 ); \
	fla_dim_t              n_left    = n_left32 % ( 4 * 1 ); \
	fla_dim_t              i; \
\
	const fla_dim_t        step_a1 = inc_a1 * 4; \
	const fla_dim_t        step_a2 = inc_a2 * 4; \
\
	float*  restrict alpha1 = a1; \
	float*  restrict alpha2 = a2; \
\
	v4sf_t           a1v, a2v; \
	v4sf_t           g12v, s12v; \
	v4sf_t           t1v; \
\
	g12v.v = _mm_load1_ps( gamma12 ); \
	s12v.v = _mm_load1_ps( sigma12 ); \
\
	for ( i = 0; i < n_iter32; ++i ) \
	{ \
\
		a1v.v = _mm_load_ps( ( float* )alpha1 ); \
		a2v.v = _mm_load_ps( ( float* )alpha2 ); \
\
